setTimeout(()=>{const baseHistoryWithPhases=renderHistory,splitFirstWeek=()=>{const history=$('#history');if(!history||!history.children.length)return;const start=new Date(`${state.startDate}T00:00:00`),today=new Date();today.setHours(0,0,0,0),makePhase=(label,offset,length)=>{const phaseStart=new Date(start);phaseStart.setDate(phaseStart.getDate()+offset);const phaseEnd=new Date(phaseStart);phaseEnd.setDate(phaseEnd.getDate()+length-1);const programEnd=state.endDate?new Date(`${state.endDate}T00:00:00`):null,cappedEnd=programEnd&&programEnd<phaseEnd?programEnd:phaseEnd,status=phaseStart>today?'진행 예정':cappedEnd<today?'완료':'진행 중',rows=state.records.filter(record=>record.date>=fmt(phaseStart)&&record.date<=fmt(cappedEnd)&&(!state.endDate||record.date<=state.endDate)).sort((a,b)=>a.date.localeCompare(b.date)),latest=rows.at(-1),summary=latest?`근육량 ${Number(latest.muscle)-getMuscleBaseline()>0?'+':''}${(Number(latest.muscle)-getMuscleBaseline()).toFixed(1)}kg · 체지방 ${fatMass(latest)-initial.fat>0?'+':''}${(fatMass(latest)-initial.fat).toFixed(1)}kg`:'해당 단계 측정 기록 없음',upcoming=status==='진행 예정';return `<article class="history-item${upcoming?' upcoming':''}"><header><div><h3>${label}</h3><small>${String(phaseStart.getMonth()+1).padStart(2,'0')}.${String(phaseStart.getDate()).padStart(2,'0')} – ${String(cappedEnd.getMonth()+1).padStart(2,'0')}.${String(cappedEnd.getDate()).padStart(2,'0')}</small></div><span class="history-status ${upcoming?'upcoming-status':''}">${status}</span></header><p>${upcoming?'예정된 프로그램 일정':'초기 기준 및 단계별 측정 기록'}</p><strong>${upcoming?`${String(phaseStart.getMonth()+1).padStart(2,'0')}.${String(phaseStart.getDate()).padStart(2,'0')} 시작 · ${length}일 일정`:summary}</strong></article>`},rest=[...history.children].slice(1).map(card=>card.outerHTML);history.innerHTML=[makePhase('1주차 1단계',0,3),makePhase('1주차 2단계',3,4),...rest].join('')};renderHistory=()=>{baseHistoryWithPhases();splitFirstWeek()};renderHistory()},0);
