setTimeout(()=>{const clearData=$('#clearData');if(clearData)clearData.onclick=()=>{if(!confirm('현재 프로그램과 이전 프로그램 기록을 모두 삭제하고 새 상태로 시작할까요? 저장한 JSON 파일이 있다면 먼저 저장하세요.'))return;localStorage.removeItem(KEY);location.reload()};const startForm=$('#startForm');if(startForm)startForm.addEventListener('submit',event=>{if(startSetupMode!=='new'||state.programId!=='demo-program')return;const nextStart=$('#startDateInput').value,nextEnd=$('#endDateInput').value;if(nextEnd&&nextEnd<nextStart){event.preventDefault();event.stopImmediatePropagation();alert('종료일은 시작일 이후로 설정하세요.');return}if(!confirm('데모 데이터와 데모 이전 기록을 제거하고 새 프로그램을 시작할까요?')){event.preventDefault();event.stopImmediatePropagation();return}event.preventDefault();event.stopImmediatePropagation();const previousState=Object.assign(currentProgramSnapshot(),{programs:clone(state.programs)}),newProgramId=`program-${nextStart}-${Date.now()}`;state.programs=[];state.programId=newProgramId;state.lastProgramTransition={archiveId:null,newProgramId,previousState};state.records=[];state.fastingDays=[];state.decisionChecks={training:'unknown',fatigue:'unknown',protein:'unknown'};state.startDate=nextStart;state.endDate=nextEnd||'';const d=new Date(`${state.startDate}T00:00:00`),today=new Date();today.setHours(0,0,0,0);state.stage=Math.max(1,Math.floor((today-d)/604800000)+1);state.repeat=1;state.selected=d;state.year=d.getFullYear();state.month=d.getMonth();persist();$('#startDialog').close();renderStageSummary();renderCalendar();renderHistory();renderChart();renderRecords();renderProgramArchives();syncProgramActions()},true)},0);
function enterArchivedProgramView(id){const program=state.programs.find(item=>item.id===id);if(!program)return;if(!state.viewingProgramId)state.liveProgramSnapshot=currentProgramSnapshot();const selected=program.selected?new Date(program.selected):new Date(`${program.startDate}T00:00:00`);Object.assign(state,clone(program),{selected,viewingProgramId:id,viewOnly:true});renderStageSummary();renderCalendar();renderHistory();renderChart();renderRecords();renderProgramArchives();syncProgramActions();$('#programViewBanner').hidden=false;window.scrollTo({top:0,behavior:'smooth'})}
function leaveArchivedProgramView(){if(!state.viewingProgramId||!state.liveProgramSnapshot)return;const live=clone(state.liveProgramSnapshot);Object.assign(state,live);if(typeof state.selected==='string')state.selected=new Date(state.selected);delete state.liveProgramSnapshot;delete state.viewingProgramId;delete state.viewOnly;renderStageSummary();renderCalendar();renderHistory();renderChart();renderRecords();renderProgramArchives();syncProgramActions();$('#programViewBanner').hidden=true;window.scrollTo({top:0,behavior:'smooth'})}
const baseProgramArchiveRender=renderProgramArchives;renderProgramArchives=()=>{baseProgramArchiveRender();const select=$('#programSelect'),live=state.liveProgramSnapshot;if(!select)return;if(live){const option=select.querySelector('option[value="current"]');if(option)option.textContent=`현재 프로그램 · ${live.startDate.replaceAll('-','.')} · 진행 중`;select.value=state.viewingProgramId||'current';$('#programStatus').textContent='과거 프로그램 조회 중';$('#programStatus').className='program-status'}$('#programViewBanner').hidden=!state.viewingProgramId};
setTimeout(()=>{const viewButton=$('#viewProgram');if(viewButton)viewButton.onclick=()=>{const id=$('#programSelect').value;if(id==='current'){if(state.viewingProgramId)leaveArchivedProgramView();else $('.hero-card').scrollIntoView({behavior:'smooth',block:'start'});return}enterArchivedProgramView(id)};const returnButton=$('#returnCurrentProgram');if(returnButton)returnButton.onclick=leaveArchivedProgramView;['#openRecord','#setStartDate','#newProgram','#repeatStage','#advanceStage'].forEach(selector=>{const button=$(selector);if(button)button.addEventListener('click',event=>{if(!state.viewOnly)return;event.preventDefault();event.stopImmediatePropagation();alert('과거 프로그램 조회 중에는 변경할 수 없습니다. 현재 프로그램으로 돌아간 후 수정하세요.')},true)})},0);
setTimeout(()=>{if(state.programId!=='demo-program'||state.demoVersion===4)return;const archived=(id,startDate,endDate,records,archivedAt)=>({id,programId:id,startDate,endDate,height:170,stage:4,repeat:1,month:Number(startDate.slice(5,7))-1,year:Number(startDate.slice(0,4)),selected:`${endDate}T00:00:00.000Z`,chart:'muscle',chartRange:'initial',records:clone(records),fastingDays:[],decisionChecks:{training:'ok',fatigue:'ok',protein:'ok'},archivedAt});state.records=clone(demoRecords);state.programs=[archived('demo-older-program','2026-06-15','2026-07-13',demoOlderRecords,'2026-07-14T00:00:00.000Z'),archived('demo-previous-program','2026-09-21','2026-10-18',demoPreviousRecords,'2026-10-19T00:00:00.000Z')];state.demoVersion=4;persist();renderCalendar();renderChart();renderHistory();renderProgramArchives()},0);
const failureGuideHtml=`<section class="guide-phase failure-guide"><h3>주차별 주요 실패 패턴</h3><div class="guide-table-wrap"><table class="guide-table"><thead><tr><th>구분</th><th>자주 나타난 행동</th><th>결과</th></tr></thead><tbody><tr><th>1주차</th><td>집에 머무는 주말에 간식 유혹에 노출</td><td>식단 이탈 위험 증가</td></tr><tr><th>2주차</th><td>시간이 부족하거나 힘이 없어 운동을 거름</td><td>체중 감소에도 근육량 감소</td></tr><tr><th>3주차</th><td>단식을 한 번만 수행하고 행사·여행 중 간식 섭취</td><td>체중 증가와 식단 흐름 이탈</td></tr><tr><th>4주차</th><td>종료 후 보상심리로 빵·디저트·탄수화물 섭취 확대</td><td>체중 회복과 식습관 붕괴</td></tr></tbody></table></div><p>특히 2주차는 체중 숫자만으로 성패를 판단하기 어렵습니다. 체중이 줄어도 운동 부족과 에너지 저하가 겹치면 근육량이 함께 감소할 수 있으므로 체중·체지방·근육량·컨디션을 함께 확인하세요. 4주차 이후에는 종료가 새로운 식습관 형성의 전환점이 될 수 있습니다.</p></section><section class="guide-phase failure-guide"><h3>주의해야 할 실패 케이스와 원인</h3><div class="guide-table-wrap"><table class="guide-table"><thead><tr><th>주의 케이스</th><th>드러난 원인</th><th>대응 방향</th></tr></thead><tbody><tr><th>술자리 지속</th><td>알코올 섭취와 늦은 시간 안주</td><td>음주 제한과 대체 식사 준비</td></tr><tr><th>극심한 무기력</th><td>하루 네 차례 식사에 대한 부담</td><td>식사 횟수와 강도 재검토</td></tr><tr><th>수술·수액 뒤 시행</th><td>부종과 활동 제한</td><td>정상적인 식사·활동 회복 우선</td></tr><tr><th>단식 후 보상 소비</th><td>“끝나면 먹겠다”는 보상심리</td><td>작은 양으로 나누고 즉시 복귀</td></tr><tr><th>자가 제조 간식</th><td>밀가루·당류 제품을 직접 대량 생산</td><td>허용 식품 중심의 간단한 식사</td></tr><tr><th>엄격한 완벽주의</th><td>한 번의 실수로 전체 중단</td><td>다음 식사부터 바로 복귀</td></tr></tbody></table></div><p class="guide-note">몸 상태가 좋지 않거나 수술·수액 뒤 부종이 있는 특수한 상황이라면 기존 방식의 강행보다 정상적인 식사와 활동 회복, 필요 시 의료진 상담을 우선하세요.</p></section><section class="guide-phase failure-guide"><h3>실패 시 재도전 및 관리 팁</h3><ul><li>한 끼를 어겼다면 처음부터 다시 시작하기보다 다음 식사부터 정해진 식단으로 돌아갑니다.</li><li>주말에는 간식을 눈에 띄지 않게 치우고 외출·대화·취미로 유혹 노출을 줄입니다.</li><li>운동은 낮은 강도부터 다시 시작하고, 시간과 체력에 맞는 실행 가능한 목표를 정합니다.</li><li>단식 뒤에는 보상 식사를 피하고 허용 식품을 소량으로 준비합니다.</li><li>식사뿐 아니라 무기력, 운동 여부, 술자리, 간식 종류를 기록해 반복되는 실패 조건을 찾습니다.</li><li>극심한 무기력이나 불편감이 생기면 강도를 낮추고 식사 횟수와 단식 일정을 다시 살펴봅니다.</li></ul></section>`;
const baseRenderDietGuideWithFailures=renderDietGuide;renderDietGuide=week=>{baseRenderDietGuideWithFailures(week);$('#guideBody').insertAdjacentHTML('beforeend',failureGuideHtml)};
const foodRulesGuideHtml=`<section class="guide-phase food-rules-guide"><h3>주차별 허용 식품과 금지 식품</h3><p>주차가 진행될수록 허용 식품을 단계적으로 넓혀가되, 빵·면·과자·설탕·액상과당·술은 기본적으로 피합니다. 프로그램 판본이나 개인 상태에 따라 세부 허용 범위가 달라질 수 있습니다.</p><h4>1주차 허용 식품과 금지 식품</h4><div class="guide-table-wrap"><table class="guide-table"><thead><tr><th>구분</th><th>허용 식품</th><th>금지 식품</th></tr></thead><tbody><tr><th>1~3일차</th><td>단백질 쉐이크, 녹황색 채소, 두부, 코코넛오일, 무가당 요거트</td><td>고체 음식, 설탕류, 밀가루 음식, 술</td></tr><tr><th>4~7일차</th><td>잡곡밥 반 공기, 채소, 단백질 식품</td><td>밥·면·감자·고구마, 설탕·액상과당</td></tr><tr><th>허기 보완</th><td>무가당 플레인 요거트, 두부, 양배추, 브로콜리</td><td>당분이 들어간 간식</td></tr></tbody></table></div><p class="guide-note">초반 허기가 심하면 허용 식품으로 보완하고, 밥·면·감자·고구마처럼 탄수화물 비중이 높은 식품으로 대체하지 않도록 합니다.</p><h4>2주차 허용 식품과 추가 규칙</h4><div class="guide-table-wrap"><table class="guide-table"><thead><tr><th>구분</th><th>허용 식품</th><th>추가 규칙</th></tr></thead><tbody><tr><th>단백질</th><td>닭고기, 생선, 달걀, 두부, 콩류</td><td>저녁은 밥 없이 단백질·채소 중심</td></tr><tr><th>탄수화물</th><td>현미밥·잡곡밥 또는 흰쌀밥 소량</td><td>점심에만 제한적으로 섭취</td></tr><tr><th>채소</th><td>브로콜리, 양배추, 버섯, 잎채소</td><td>식사에 다양하게 활용</td></tr><tr><th>간식</th><td>무가당 견과류 소량</td><td>아몬드·호두 등</td></tr><tr><th>음료</th><td>설탕·시럽 없는 블랙커피</td><td>오전 중 한 잔</td></tr></tbody></table></div><p class="guide-note">당뇨병 약 복용·저혈당 경험, 임신·수유, 섭식장애 병력이 있다면 24시간 단식은 피하고 의료진과 상담하세요.</p><h4>3주차와 4주차 식품 확장 및 안정화</h4><div class="guide-table-wrap"><table class="guide-table"><thead><tr><th>구분</th><th>허용 식품</th><th>운영 방식</th></tr></thead><tbody><tr><th>3주차</th><td>단호박, 밤, 플레인 요거트, 베리류 과일 소량</td><td>간식으로 소량 추가</td></tr><tr><th>3주차 단식</th><td>확장된 허용 식품 범위</td><td>주 2회, 서로 떨어진 요일에 실시</td></tr><tr><th>4주차</th><td>3주차 식단 유지</td><td>주 2회 단식 또는 몸 상태에 따라 주 1회</td></tr><tr><th>4주차 일반식</th><td>양질의 식단</td><td>밥을 무조건 제한하지 않고 양 조절</td></tr></tbody></table></div><p>3주차부터 과일·곡류를 쉽게 늘리지 않도록 소량 기준을 지키고, 4주차에는 단식 횟수를 줄이더라도 식사의 질을 유지합니다. 종료 후에도 탄수화물과 간식을 갑자기 늘리지 않는 것이 안정화에 중요합니다.</section>`;
const baseRenderDietGuideWithFoodRules=renderDietGuide;renderDietGuide=week=>{baseRenderDietGuideWithFoodRules(week);$('#guideBody').insertAdjacentHTML('beforeend',foodRulesGuideHtml)};
const maintenanceGuideHtml=`<section class="guide-phase maintenance-guide"><h3>유지기 관리지침</h3><p>유지기는 프로그램이 끝난 뒤에도 체중과 체성분의 흐름을 관리하며 새로운 식습관을 정착하는 기간입니다. 하루의 숫자보다 최근 추세와 복부 둘레, 근육량·체지방률을 함께 확인하세요.</p><h4>유지기 핵심 관리 원칙</h4><div class="guide-table-wrap"><table class="guide-table"><thead><tr><th>관리 항목</th><th>유지기 실천 기준</th><th>관리 포인트</th></tr></thead><tbody><tr><th>체중 확인</th><td>매일 아침 공복 체중 측정</td><td>일시적 상승보다 지속 경향 확인</td></tr><tr><th>공복 관리</th><td>저녁 식사 후 12~14시간</td><td>첫 식사 시점을 일정하게 유지</td></tr><tr><th>단백질</th><td>매 끼니 단백질 포함</td><td>포만감과 근육량 유지</td></tr><tr><th>탄수화물</th><td>신체 활동량에 맞춰 조절</td><td>활동이 적은 날은 섭취량 축소</td></tr><tr><th>과일</th><td>하루 1~2개 이내</td><td>특히 오후 섭취 제한</td></tr><tr><th>운동</th><td>꾸준한 운동과 잦은 움직임</td><td>앉아 있는 시간 중간에 활동 추가</td></tr><tr><th>외식·휴식</th><td>원하는 음식은 제한적으로 허용</td><td>다음 식사부터 바로 복귀</td></tr></tbody></table></div><p class="guide-note">체중이 조금 늘었다면 먹는 양을 급격히 줄이기보다 운동이나 일상 활동을 늘려 보세요. 체중과 복부 둘레가 계속 증가하면 식사와 활동 강도를 다시 점검합니다.</p><h4>단식과 운동 전략</h4><ul><li>주 1회 단식을 유지할 수 있지만, 한 번의 단식 결과만으로 감량 효과를 보장한다고 판단하지 않습니다.</li><li>단식일에는 무리한 운동보다 컨디션에 맞는 걷기·가벼운 활동으로 활동량을 확보합니다.</li><li>평일 운동을 놓쳤다면 자전거·산책·이동량을 늘려 완전히 쉬는 날을 줄입니다.</li></ul><h4>수면과 생활 습관</h4><ul><li>수면은 최소 7시간을 목표로 하고 취침·기상 시간을 일정하게 유지합니다.</li><li>취침 2시간 전부터 조명을 어둡게 하고 영상 기기 사용을 줄입니다.</li><li>운동은 가능하면 취침 3시간 전까지 마치고, 30분마다 잠깐씩 움직입니다.</li><li>음주와 저녁 식사 뒤 늦은 음식 섭취를 줄여 수면과 활동 리듬을 함께 관리합니다.</li></ul><h4>장기 유지와 체중 변동 대응</h4><ul><li>300일 이상 기록한 사례처럼 체중·복부 둘레·식욕·주말 이탈 조건을 함께 남기면 반복 패턴을 찾기 쉽습니다.</li><li>밀프랩이나 도시락을 활용하면 평일 외식과 즉흥적인 간편식 선택을 줄일 수 있습니다. 소스는 당류와 열량을 확인하세요.</li><li>외식이나 여행 뒤에는 다음 날부터 바로 평소 식사로 복귀하고, 한 번의 이탈을 폭식이나 전체 포기로 이어가지 않습니다.</li><li>일시적으로 체중이 0.8kg 정도 오를 수 있으므로 회복 여부와 지속성을 확인합니다.</li><li>체중이 비슷해도 근육량이 줄고 체지방률이 오를 수 있으므로 체중만으로 유지 성공 여부를 판단하지 않습니다.</li><li>체중·복부 둘레 증가와 간식 요구가 반복되면 재도전을 검토하되, 건강 상태와 생활 환경을 먼저 점검합니다.</li></ul></section>`;
const baseRenderDietGuideWithMaintenance=renderDietGuide;renderDietGuide=week=>{baseRenderDietGuideWithMaintenance(week);$('#guideBody').insertAdjacentHTML('beforeend',maintenanceGuideHtml)};
const renderDietGuideWithMaintenanceTab=renderDietGuide;renderDietGuide=week=>{if(week==='maintenance'){$('#guideTitle').textContent='유지기 관리지침';$('#guideBody').innerHTML=`<p>4주차 이후에는 감량을 계속 밀어붙이기보다 체중과 체성분의 흐름을 안정적으로 관리하세요.</p>${maintenanceGuideHtml}`;document.querySelectorAll('[data-guide-week]').forEach(button=>{const active=button.dataset.guideWeek===week;button.classList.toggle('active',active);button.setAttribute('aria-selected',String(active))});return}renderDietGuideWithMaintenanceTab(week);$('#guideBody .maintenance-guide')?.remove()};
setTimeout(()=>{const tabs=$('.guide-tabs');if(!tabs||tabs.querySelector('[data-guide-week="maintenance"]'))return;const button=document.createElement('button');button.type='button';button.dataset.guideWeek='maintenance';button.setAttribute('role','tab');button.textContent='유지기';button.onclick=()=>renderDietGuide('maintenance');tabs.append(button)},0);
const foodTableHtml=`<h3>허용 식품 가이드</h3><p>단계가 진행될수록 허용 식품을 조금씩 넓혀 식단을 구성합니다.</p><div class="guide-table-wrap"><table class="guide-table food-guide-table"><thead><tr><th>단계</th><th>허용 식품</th><th>운영 포인트</th></tr></thead><tbody><tr><th>기본 허용</th><td>물 하루 8컵 이상, 무가당 플레인 요거트, 녹황색 채소·오이, 두부·연두부, 허브티</td><td>모든 단계에서 기본 식품으로 활용</td></tr><tr><th>1단계<br><small>1~3일차</small></th><td>단백질 쉐이크 4회, 기본 허용 식품</td><td>고체 음식 제한, 물·허브티 활용</td></tr><tr><th>2단계<br><small>4~7일차</small></th><td>생선·해산물, 닭고기, 달걀, 버섯류, 해조류</td><td>단백질·채소 중심으로 구성</td></tr><tr><th>3단계<br><small>2주차</small></th><td>콩류·견과류, 짜지 않은 천연 치즈, 우유, 약간의 김치</td><td>견과류·우유는 소량</td></tr><tr><th>4단계<br><small>3주차</small></th><td>단호박·토마토, 방울토마토, 바나나·베리류, 고구마</td><td>과일·탄수화물은 소량, 고강도 운동 후 고구마 가능</td></tr><tr><th>공통 금지</th><td colspan="2">술, 설탕류, 밀가루, 트랜스지방, 가공식품, 탄산음료</td></tr></tbody></table></div><p class="guide-note">허용 범위는 프로그램 판본과 개인 건강 상태에 따라 달라질 수 있습니다. 당뇨·저혈당·임신·수유·섭식장애 병력이 있다면 식단과 단식은 의료진과 상의하세요.</p>`;
const baseRenderDietGuideWithFoodTable=renderDietGuide;renderDietGuide=week=>{baseRenderDietGuideWithFoodTable(week);const foodPhase=$('#guideBody .food-phase');if(foodPhase)foodPhase.innerHTML=foodTableHtml};
const baseRenderDietGuideWithCautionColumn=renderDietGuide;renderDietGuide=week=>{baseRenderDietGuideWithCautionColumn(week);const caution=[...document.querySelectorAll('#guideBody .failure-guide')].find(section=>section.querySelector('h3')?.textContent.includes('주의해야 할 실패'));caution?.classList.add('caution-failure-guide')};
const maintenanceExtensionGuideHtml=`<section class="guide-phase maintenance-extension-guide"><h3>4주차 종료 후 반복 판단</h3><p>기본 흐름은 4주차를 마친 뒤 유지기로 전환하는 것입니다. 4주차 반복은 자동 진행이 아니라 추가 감량을 위한 선택적 연장으로 봅니다.</p><h4>4주차 반복·연장을 고려할 수 있는 경우</h4><ul><li>체지방과 체중이 아직 꾸준히 감소하고 있습니다.</li><li>근육량이 크게 줄지 않고 운동 수행과 회복 상태가 양호합니다.</li><li>피로·무기력·수면 저하 없이 식단과 단식을 무리 없이 수행하고 있습니다.</li><li>유지기로 전환하기보다 추가 감량이 필요하다는 목표가 분명합니다.</li></ul><h4>유지기 또는 상담을 우선할 경우</h4><ul><li>체지방 감소가 멈추고 체중도 정체되어 있습니다.</li><li>근육량이 계속 감소하거나 운동 수행력이 떨어집니다.</li><li>극심한 무기력·어지러움·수면 악화가 나타납니다.</li><li>단식 후 폭식이나 식단 이탈이 반복됩니다.</li><li>당뇨약 복용·저혈당 경험, 임신·수유, 섭식장애 병력 등 주의 상황이 있습니다.</li></ul><p class="guide-note">공개 정리 자료에는 체지방이 계속 감소하고 몸 상태가 양호한 경우 4주차 패턴을 8~12주까지 연장할 수 있다는 설명도 있지만, 판본과 개인 상태에 따라 다를 수 있습니다. 수치 하나만으로 반복하지 말고 체성분 추세와 컨디션을 함께 확인하세요.</p></section>`;
const baseRenderDietGuideWithExtension=renderDietGuide;renderDietGuide=week=>{baseRenderDietGuideWithExtension(week);if(week==='maintenance')$('#guideBody').insertAdjacentHTML('beforeend',maintenanceExtensionGuideHtml)};
const livedFailureGuideHtml=`<section class="guide-phase lived-failure-guide"><h3>실제 사례에서 반복된 실패 유형</h3><p>치팅 범위가 한 끼에서 하루·이틀, 매일로 확대되거나 주말 간식·술자리·외식·운동 부족이 겹치면 체중이 2~3kg 늘고 프로그램을 중단하기 쉬웠다는 사례가 있습니다.</p><h4>프로그램 미준수와 치팅데이 확대</h4><div class="guide-table-wrap"><table class="guide-table"><thead><tr><th>실패 유형</th><th>구체적인 모습</th><th>결과</th></tr></thead><tbody><tr><th>규정 외 식품 섭취</th><td>단식일에 초코 과자와 우유 섭취</td><td>식단 이탈과 재시작 여부 갈등</td></tr><tr><th>단식 뒤 폭식</th><td>피자·면·전·술 등을 한꺼번에 섭취</td><td>체중 상승과 식단 중단</td></tr><tr><th>치팅 범위 확대</th><td>점심 한 끼에서 저녁, 하루 전체로 확대</td><td>한 달간 체중 2~3kg 증가</td></tr><tr><th>프로그램 개념 오해</th><td>일반 단백질 쉐이크만으로 대체</td><td>영양 구성과 기간 관리에 혼선</td></tr></tbody></table></div><p class="guide-note">치팅은 무제한으로 먹는 날이 아니라, 허용 범위를 미리 정하고 다음 식사부터 정해진 식단으로 돌아오는 기준을 포함해야 합니다. 단식 직후에는 허기가 커질 수 있으므로 치팅을 단식일과 같은 날에 배치하지 않는 편이 안전합니다.</p><h4>주말과 사회적 상황에서의 간식 유혹</h4><div class="guide-table-wrap"><table class="guide-table"><thead><tr><th>상황</th><th>실패 사례</th><th>개선 방향</th></tr></thead><tbody><tr><th>주말 귀가</th><td>집에 오래 머물며 간식에 반복 노출</td><td>간식 노출을 줄이고 대체 식사 준비</td></tr><tr><th>외식</th><td>면·파스타·브런치 등을 계획 없이 섭취</td><td>외식 전후 식사량을 미리 조절</td></tr><tr><th>술자리</th><td>연휴에 술 약속이 이어짐</td><td>약속 전후 식단과 음주량 설정</td></tr><tr><th>가족 돌봄</th><td>식단 준비와 운동을 함께 하기 어려움</td><td>긴 계획보다 가능한 한 끼부터 복귀</td></tr><tr><th>양념 의존</th><td>채소에 단맛·고열량 양념을 반복 사용</td><td>허용 양념을 미리 정해두기</td></tr></tbody></table></div><h4>운동 부족·정체기·생활 환경 요인</h4><div class="guide-table-wrap"><table class="guide-table"><thead><tr><th>요인</th><th>실패 사례</th><th>관리 방향</th></tr></thead><tbody><tr><th>정체기와 흥미 저하</th><td>감량 후 정체기에 식단 의욕 감소</td><td>체중보다 식사 습관 기록</td></tr><tr><th>운동 부족</th><td>유산소만 선호하고 근력 운동을 미룸</td><td>가능한 범위에서 근력 활동 추가</td></tr><tr><th>육아와 체력 저하</th><td>돌봄으로 운동할 시간과 체력이 부족</td><td>운동보다 식단 복귀를 우선</td></tr><tr><th>준비물 과잉</th><td>식품과 보조물을 준비했지만 시작하지 못함</td><td>구매보다 실행 가능한 한 끼 선정</td></tr><tr><th>반복 실패</th><td>여러 차례 시도하며 실패 경험 누적</td><td>완벽한 재시작보다 오류 수정</td></tr></tbody></table></div><p>운동을 하지 못했다고 식단까지 포기할 필요는 없습니다. 다만 정체기에는 체력에 맞는 작은 활동과 식사 기록을 함께 시작하면 지속성을 높이는 데 도움이 됩니다.</section>`;
const baseRenderDietGuideWithLivedFailures=renderDietGuide;renderDietGuide=week=>{baseRenderDietGuideWithLivedFailures(week);if(week!=='maintenance')$('#guideBody').insertAdjacentHTML('beforeend',livedFailureGuideHtml)};
const snackGuideHtml=`<section class="guide-phase snack-guide"><h3>허기 보완용 보조 간식 가이드</h3><p>보조 간식은 식사를 대체하거나 무제한으로 먹는 용도가 아닙니다. 제품마다 당류·열량·단백질 함량이 다르므로 포장지의 영양성분을 확인하고 정해진 양만 활용하세요.</p><div class="guide-table-wrap"><table class="guide-table"><thead><tr><th>선택지</th><th>활용 방법</th><th>주의사항</th></tr></thead><tbody><tr><th>곤약 젤리</th><td>회사에서 일반식을 먹기 전 허기나 단맛 욕구를 잠시 줄이는 보조 간식</td><td>식사 대용으로 과하게 먹지 않기</td></tr><tr><th>고단백 스낵</th><td>씹는 간식이 필요할 때 1회 제공량을 정해 활용</td><td>단백질·당류·열량과 1봉지 분량 확인</td></tr><tr><th>분말형 대체 간식</th><td>달콤한 음료가 당길 때 무가당·무카페인 제품을 물이나 얼음물에 활용</td><td>특정 기능·효능을 기대하지 말고 성분표 확인</td></tr><tr><th>무가당 그릭 요거트</th><td>저당 감미료와 과일·견과류를 소량 더해 얼린 요거트 바크로 활용</td><td>추가 재료의 당류·열량까지 함께 확인</td></tr><tr><th>낫또 간식</th><td>김 위에 낫또와 닭가슴살 또는 참치를 올려 간단히 섭취</td><td>항응고제 복용 중이면 비타민 K 상호작용을 의료진과 상담</td></tr></tbody></table></div><p class="guide-note">제품명이나 영양성분은 판매 시점과 제품별로 달라질 수 있습니다. 곤약 젤리·스낵·보충제는 허용 식품을 대체하는 만능 식품이 아니라, 상황에 맞게 양을 조절하는 보조 선택지입니다.</p></section>`;
const baseRenderDietGuideWithSnackGuide=renderDietGuide;renderDietGuide=week=>{baseRenderDietGuideWithSnackGuide(week);if(week!=='maintenance')$('#guideBody').insertAdjacentHTML('beforeend',snackGuideHtml)};
const additionalFailureGuideHtml=`<section class="guide-phase additional-failure-guide"><h3>주요 실패 유형 및 원인 분석</h3><div class="guide-table-wrap"><table class="guide-table"><thead><tr><th>실패 유형</th><th>실제 사례</th><th>위험 요소</th></tr></thead><tbody><tr><th>주말 식단 이탈</th><td>친구 모임과 늦은 귀가</td><td>허용되지 않은 음식 섭취</td></tr><tr><th>단백질 쉐이크 누락</th><td>늦잠으로 주말에 여러 차례 거름</td><td>정해진 식사 구성 유지 어려움</td></tr><tr><th>허용 식품의 과도한 선택</th><td>허용 식품 중 맛있는 음식을 주로 선택</td><td>섭취량과 영양 구성 관리 어려움</td></tr><tr><th>단식 계획 부재</th><td>단식이 물리거나 계획 없이 시행</td><td>단식일과 식사일 구분 혼선</td></tr><tr><th>일반식 전환 후 폭식</th><td>영화관에서 핫도그와 팝콘 섭취</td><td>외부 행사에서 선택지 통제 어려움</td></tr><tr><th>생리 주기 영향</th><td>생리 중 배달 음식과 단식 일정을 임의 변경</td><td>허기와 신체 변화에 따른 계획 흔들림</td></tr><tr><th>정체기 반응</th><td>체중과 체지방 정체에 무리하게 추진</td><td>휴식과 활동량 조절 기회 상실</td></tr></tbody></table></div><p>‘하나를 먹었으니 끝났다’는 생각과 외부 행사 대안 부족이 반복적인 이탈로 이어질 수 있습니다. 생리·피로 등 신체 변화가 겹치면 단식과 식사 결정을 임의로 바꾸기 쉬우므로, 계획을 완벽하게 지키기보다 다음 식사부터 현실적으로 복귀하는 기준을 세우세요.</p></section>`;
const maintenanceRestartGuideHtml=`<section class="guide-phase maintenance-restart-guide"><h3>유지기 관리 원칙과 재시작 전략</h3><div class="guide-table-wrap"><table class="guide-table"><thead><tr><th>관리 영역</th><th>유지기 원칙</th><th>재시작 전략</th></tr></thead><tbody><tr><th>체중 확인</th><td>아침 공복 체중으로 변화 관찰</td><td>하루 증감보다 지속 흐름 확인</td></tr><tr><th>식사 구성</th><td>일반식과 단백질 쉐이크를 계획에 포함</td><td>허용 식품과 섭취량을 다시 설정</td></tr><tr><th>공복 관리</th><td>14시간 공복과 하루 세 끼 식사</td><td>첫 식사 시점을 고정</td></tr><tr><th>활동량</th><td>걷기와 스트레칭부터 점진적으로 확대</td><td>운동 부족 구간에 가벼운 활동 추가</td></tr><tr><th>외식 대응</th><td>메뉴와 섭취량을 미리 결정</td><td>이탈 후 다음 식사부터 즉시 복귀</td></tr><tr><th>정체기 대응</th><td>무리한 감량보다 휴식과 활동량 조절</td><td>식사 기록으로 이탈 원인 점검</td></tr><tr><th>재도전 시점</th><td>최소 3~4주 유지 후 검토</td><td>체중·식습관이 불안정하면 유지기간 연장</td></tr></tbody></table></div><p>유지기에 체중이 늘었다고 곧바로 재시작하기보다 먹는 양과 활동량을 먼저 조정하세요. 재도전이 필요하다면 최소 3~4주 유지 후 정해진 식단·공복 시간과 외부 행사 메뉴를 다시 계획하는 편이 현실적입니다.</p></section>`;
const baseRenderDietGuideWithRestart=renderDietGuide;renderDietGuide=week=>{baseRenderDietGuideWithRestart(week);$('#guideBody').insertAdjacentHTML('beforeend',week==='maintenance'?maintenanceRestartGuideHtml:additionalFailureGuideHtml)};
setTimeout(()=>{const dialog=$('#dietGuideDialog'),head=dialog?.querySelector('.dialog-head');if(!dialog||!head||head.querySelector('.guide-fullscreen-toggle'))return;const button=document.createElement('button');button.type='button';button.className='secondary-button guide-fullscreen-toggle';button.textContent='전체 화면';button.onclick=()=>{const full=dialog.classList.toggle('guide-fullscreen');button.textContent=full?'일반 화면':'전체 화면'};head.querySelector('.close-button')?.before(button);dialog.addEventListener('close',()=>{dialog.classList.remove('guide-fullscreen');button.textContent='전체 화면'})},0);
